    const fxTime = { value: 0 }, smokes = layKilns(seed).map((k, i) => fx.makeSmokeColumn({ rng: stream('kiln-smoke' + i, seed), time: fxTime, position: [k.x, PLAIN_Y + 3.5, k.z], height: 110, radius: [0.8, 11], size: [3, 20], count: detail >= 0.8 ? 84 : 44,
      color: '#b8aca0', colorTop: '#e2d8cc', shadowColor: '#84786e', ambient: '#5a504a', opacity: 0.4, wind: [WIND.direction[0], 0, WIND.direction[1]], bend: 0.8, sunDir, sunColor: rgb(H.sun).multiplyScalar(2.1) }));
    // the evening's hearth smokes over the inner city (the part's layHearths): thin, low, leaning down the same wind
    layHearths(seed).forEach(([hx, hz, hh], i) => smokes.push(fx.makeSmokeColumn({ rng: stream('hearth-smoke' + i, seed), time: fxTime, position: [hx, PLAIN_Y + hh + 0.5, hz], height: 46, radius: [0.4, 5], size: [1.6, 9], count: detail >= 0.8 ? 36 : 20,
      color: '#c4b8ac', colorTop: '#e6dcd0', shadowColor: '#8c8076', ambient: '#5a504a', opacity: 0.34, wind: [WIND.direction[0], 0, WIND.direction[1]], bend: 0.9, sunDir, sunColor: rgb(H.sun).multiplyScalar(2.1) })));
    for (const sm of smokes) scene.add(sm.object);
    await ask(0.8);
    // a few petals adrift over terraces 1 to 3 (the part's PETALS: a box laid by place, 9 m and more from the stair's line)
    const petals = fx.makeParticles({ rng: stream('petals', seed), preset: 'petals', time: fxTime, follow: false, center: PETALS.center, box: PETALS.box, count: Math.round(PETALS.count * deal.blossom * (detail >= 0.8 ? 1 : 0.5)), colors: ['#f6ece6', '#f1e0dc', '#fff8f2'], size: [0.035, 0.07], near: [0, 0.001], lightDir: sunDir });
    scene.add(petals.object);
    await ask(0.6);
    // fallen needles adrift under the cedars either side of the top walk (the part's NEEDLES: two standing boxes of air)
    const needles = NEEDLES.map((N, i) => fx.makeParticles({ rng: stream('needles' + i, seed), preset: 'petals', time: fxTime, follow: false, center: N.center, box: N.box, count: Math.round(N.count * (detail >= 0.8 ? 1 : 0.5)),
      velocity: [0.45, -0.55, 0.3], velocityRandom: [0.25, 0.2, 0.25], turbulence: [0.18, 0.08, 0.18], shape: 'leaf', aspect: 0.22, spin: 1.4, colors: ['#c2a05c', '#8c6c40', '#dcc284'], size: [0.035, 0.07], near: [0, 0.001], lightDir: sunDir }));
