      uHorAway: { value: horAway }, uHorSun: { value: horSun }, uLowAway: { value: lowAway }, uLowSun: { value: lowSun }, uBody: { value: COL.water.clone() }, uFogCol: { value: fogCol }, uBoats: { value: wakeU }, uFowl: { value: fowlU },
